    assign out_lo = in[7:0];
endmodule

module TopModule (
    input  clk,
    input  resetn,
    input  byteena,
    input  d,
    output q
);
    reg [15:0] dff;

    always @(posedge clk or negedge resetn) begin
        if (!resetn)
            dff <= 16'b0;
        else begin
            if (byteena[1])
                dff[15:8] <= d[15:8];
            if (byteena[0])
                dff[7:0] <= d[7:0];
        end
    end

    assign q = dff;
endmodule

module TopModule (
    input [1:0] A,
    input [1:0] B,
    output z
);
assign z = (A == B) ? 1 : 0;
endmodule

module TopModule (
    input  a,
    input  b,
    input  sel,
    output out
);
assign out = (sel == 0) ? a : b;
endmodule

module TopModule (
    input mode,
    input too_cold,
    input too_hot,
    input fan_on,
    output heater,
    output aircon,
    output fan
);
    always @(*) begin
        if (mode == 1) begin // Heating mode
            heater = too_cold;
            aircon = 0;
        end else if (mode == 0) begin // Cooling mode
            heater = 0;
            aircon = too_hot;
        end else begin
            heater = 0;
            aircon = 0;
        end

        fan = heater | aircon | fan_on;
    end
endmodule

module TopModule (
    input clk,
    input reset,
    input [7:0] in,
    output done
);
    reg [1:0] state;
    reg [2:0] byte_count;

    parameter IDLE = 2'b00, SEARCHING = 2'b01, RECEIVING = 2'b10;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            byte_count <= 3'b000;
            done <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (in[3]) begin
                        state <= SEARCHING;
                        byte_count <= 3'b001;
                    end
                end
                SEARCHING: begin
                    if (in[3]) begin
                        state <= RECEIVING;
                        byte_count <= 3'b010;
                    end
                end
                RECEIVING: begin
                    if (byte_count == 3'b011) begin
                        done <= 1'b1;
                        state <= IDLE;
                    end else begin
                        byte_count <= byte_count + 3'b001;
                    end
                end
            endcase
        end
    end
endmodule

module TopModule (
    input  [2:0] a,
    input  [2:0] b,
    output [2:0] out_or_bitwise,
    output        out_or_logical,
    output [5:0] out_not
);

assign out_or_bitwise = a | b;
assign out_or_logical = (a != 3'b000) || (b != 3'b000);
assign out_not[5:3] = ~b;
assign out_not[2:0] = ~a;

endmodule

module TopModule (
    input a,
    input b,
    input c,
    input d,
    output q
);
    assign q = (a & b) | (~c & d);
endmodule
